# Find all ORFs (start ATG/GTG/TTG, stop TAA/TAG/TGA) length>=75 nt, both strands
def find_orfs(s, strand):
    L=len(s)
    res=[]
    for f in range(3):
        i=f
        while i+3<=L:
            c=s[i:i+3]
            if c in ('ATG','GTG','TTG'):
                j=i
                while j+3<=L and s[j:j+3] not in ('TAA','TAG','TGA'):
                    j+=3
                if j+3<=L and (j+3-i)>=75:
                    if strand=='+': coords=(i+1,j+3)
                    else: coords=(L-(j+3)+1, L-i)
                    prot=''.join(codon[s[k:k+3]] for k in range(i,j,3))
                    res.append((coords,prot,c))
                i=j+3
            else:
                i+=3
    return res
